1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export type Step = QuoteStep | ClaimStep;
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	export interface ClaimStep {
21	  op: "claim";
22	  policy: number;
23	  incident: Incident;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
37	
38	export interface ScenarioResult {
39	  results: StepResult[];
40	}
41	
42	const PROCESSING_FEE = 5;
43	
44	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
45	  sword: 100,
46	  staff: 80,
47	  amulet: 60,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	};
52	
53	const FIRST_INSURANCE_PERCENT = 10;
54	
55	// Surcharges are applied as (amount * percent) / 100 rather than via a decimal
56	// multiplier (e.g. * 1.1): the integer intermediate is exact, whereas 100 * 1.1
57	// is 110.00000000000001 in binary floating point. Since the final amount feeds
58	// straight into Math.ceil, that error would round a 115 G premium up to 116 G.
59	const addPercent = (amount: number, percent: number): number =>
60	  amount + (amount * percent) / 100;
61	
62	const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
63	
64	const BLOCK_SIZE = 3;
65	const BLOCK_BASE_PREMIUM = 60;
66	
67	const sumItemBasePremiums = (items: Item[]): number =>
68	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
69	
70	const groupByType = (items: Item[]): Item[][] => {
71	  const groups = new Map<string, Item[]>();
72	  for (const item of items) {
73	    const group = groups.get(item.type) ?? [];
74	    group.push(item);
75	    groups.set(item.type, group);
76	  }
77	  return [...groups.values()];
78	};
79	
80	const formsBlock = (sameTypeItems: Item[]): boolean =>
81	  sameTypeItems.length === BLOCK_SIZE;
82	
83	const groupBasePremium = (sameTypeItems: Item[]): number =>
84	  formsBlock(sameTypeItems) ? BLOCK_BASE_PREMIUM : sumItemBasePremiums(sameTypeItems);
85	
86	const policyBasePremium = (items: Item[]): number =>
87	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
88	
89	const quotePremium = (step: QuoteStep): number =>
90	  Math.ceil(
91	    addPercent(policyBasePremium(step.items), FIRST_INSURANCE_PERCENT) +
92	      PROCESSING_FEE,
93	  );
94	
95	const runStep = (step: Step): StepResult => {
96	  if (step.op === "quote") return { premium: quotePremium(step) };
97	  throw new Error(`Unsupported step: ${step.op}`);
98	};
99	
100	export const runScenario = (scenario: Scenario): ScenarioResult => ({
101	  results: scenario.steps.map(runStep),
102	});
